def format_log_base(coeffs):
    def format_term(var_idx, p):
        if p == 1:
            return f"x_{var_idx+1}"
        return f"x_{var_idx+1}^{p}"

    pos_terms = [format_term(i, c) for i, c in enumerate(coeffs) if c > 0]
    neg_terms = [format_term(i, -c) for i, c in enumerate(coeffs) if c < 0]

    num_str = " ".join(pos_terms)
    den_str = " ".join(neg_terms)

    if not num_str and not den_str:
        return "1"
    if not num_str:
        num_str = "1"
    if not den_str:
        return num_str

    return f"\frac{{{num_str}}}{{{den_str}}}"

