        denominators = rng.sample([d for d in range(10, 51) if d % 2 == 0 or d % 3 == 0 or d % 5 == 0], n)
        numerators = [rng.randint(1, 5) for _ in range(n)]
        u = [num / den for num, den in zip(numerators, denominators)]

