        l = 1
        for num in c_num:
            l = (l * abs(num)) // math.gcd(l, abs(num))

        lambda_val = 1.0 / l
        u_prime = [val * lambda_val for val in u]

        if not all(val > 0 for val in u_prime):
            continue

        c_prime = [val * lambda_val for val in c]
        C = []
        valid_C = True
        for val in c_prime:
            if abs(val) < 1e-9:
                valid_C = False
                break
            C_val = int(round(1/val))
            if abs(1/C_val - val) > 1e-9:
                valid_C = False
                break
            C.append(C_val)
        if not valid_C:
