# Helper functions for matrix operations (no numpy)
def mat_vec_mul(A, v):
    return [sum(A[i][j] * v[j] for j in range(len(v))) for i in range(len(A))]

def float_to_frac(f, limit=1000000):
    if f == 0:
        return 0, 1
    n, d = f.as_integer_ratio()
    if d > limit:
        # Approximation for large denominator floats
        best_d = 1
        best_n = int(f)
        min_err = abs(f - best_n)
        for den in range(1, int(limit**0.5)):
            num = round(f * den)
            err = abs(f - num/den)
            if err < min_err:
                min_err = err
                best_n, best_d = num, den
        n, d = best_n, best_d
    return n, d

def lup_decompose(A):
    n = len(A)
    P = list(range(n))
    LU = [[float(A[i][j]) for j in range(n)] for i in range(n)]
    for i in range(n):
        max_val = 0.0
        max_idx = i
        for k in range(i, n):
            if abs(LU[k][i]) > max_val:
                max_val = abs(LU[k][i])
                max_idx = k
        if max_val < 1e-9: raise ValueError("Matrix is singular")
        P[i], P[max_idx] = P[max_idx], P[i]
        LU[i], LU[max_idx] = LU[max_idx], LU[i]
        for j in range(i + 1, n):
            LU[j][i] /= LU[i][i]
            for k in range(i + 1, n):
                LU[j][k] -= LU[j][i] * LU[i][k]
    return LU, P

def lup_solve(LU, P, b):
    n = len(LU)
    x = [0.0] * n
    y = [0.0] * n
    for i in range(n):
        y[i] = b[P[i]] - sum(LU[i][j] * y[j] for j in range(i))
    for i in range(n - 1, -1, -1):
        x[i] = (y[i] - sum(LU[i][j] * x[j] for j in range(i + 1, n))) / LU[i][i]
    return x

def lup_invert(A):
    n = len(A)
    LU, P = lup_decompose(A)
    inv = [[0.0] * n for _ in range(n)]
    for i in range(n):
        b = [0.0] * n
        b[i] = 1.0
        inv[i] = lup_solve(LU, P, b)
    return [[inv[j][i] for j in range(n)] for i in range(n)]

def lup_det(A):
    LU, P = lup_decompose(A)
    det = LU[0][0]
    swaps = 0
    P_orig = list(range(len(A)))
    for i, p_i in enumerate(P):
        if p_i != P_orig[i]:
            swaps += 1
            j = P_orig.index(p_i)
            P_orig[i], P_orig[j] = P_orig[j], P_orig[i]

    for i in range(1, len(A)):
        det *= LU[i][i]
    if (swaps // 2) % 2 != 0: # This is a bit tricky, should be number of swaps
        # simplified logic for permutation sign
        s = sum(1 for i in range(len(P)) if P[i] != i)
        # This is not a reliable way to count swaps. A better way:
        p_swaps = 0
        p_copy = list(P)
        for i in range(len(p_copy)):
            while p_copy[i] != i:
                j = p_copy[i]
                p_copy[i], p_copy[j] = p_copy[j], p_copy[i]
                p_swaps += 1
        if p_swaps % 2 != 0:
            det *= -1
    return det

