def verifier(assign):
    # Reconstruct the system of equations from the provided matrices and values.
    M = assign['M_matrix']
    a_star = assign['target_coeffs']
    C = [assign['c1'], assign['c2'], assign['c3']]
    n = len(M)

    # The problem requires variables > 1, so the logs should be positive.
    # This implies u_i = log_w(x_i) must be positive.
    # Also, C_k = log_{B_k}(w). If w > 1, sign(C_k) = sign(log B_k).
    # log B_k = sum(M_kj * log(x_j)). If x_j > 1, log(x_j) > 0.
    # So sign(C_k) must be consistent with sign(sum(M_kj * u_j * log w)).
    # This is equivalent to sign(C_k) = sign(1/C_k), which is always true.
    # The main constraint to check is u_i > 0 for all i.

    # Create the vector c = [1/C1, 1/C2, ...]
    c_vec = []
    for val in C:
        if val == 0:
            # log is zero, base is invalid or w=1, problem is ill-defined.
            return False, None
        c_vec.append(1.0 / val)

    # Solve the system M*u = c for u
    try:
        M_inv = lup_invert(M)
        u = mat_vec_mul(M_inv, c_vec)
    except (ValueError, ZeroDivisionError):
        # Matrix is singular, system is not uniquely solvable.
        return False, None

    # Check for non-triviality and consistency
    for val in u:
        if abs(val) < 1e-9:
            # This implies x_i = 1, which contradicts x_i > 1.
            return False, None
        if val < 0:
            # This implies either w or x_i is between 0 and 1, violating the > 1 condition for both.
            return False, None

    # Calculate the target value
    target_val = sum(a * val for a, val in zip(a_star, u))

    if abs(target_val) < 1e-9:
        # Target log is undefined.
        return False, None

    computed_answer = 1.0 / target_val

    # Check if the computed answer is close to the given integer answer
    if abs(computed_answer - assign['answer']) > 1e-6:
        return False, None

    return True, assign['answer']

